fn replace_all(
    regex: &Regex,
    input: &[u8],
    replace_with: &str,
    max_replacements: usize,
    fixed_strings: bool,
) -> Vec<u8> {
    let output: Cow<'_, [u8]> = if fixed_strings {
        if max_replacements == 0 {
            regex.replace_all(input, NoExpand(replace_with.as_bytes()))
        } else {
            regex.replacen(input, max_replacements, NoExpand(replace_with.as_bytes()))
        }
    } else if max_replacements == 0 {
        regex.replace_all(input, replace_with.as_bytes())
    } else {
        regex.replacen(input, max_replacements, replace_with.as_bytes())
    };

    output.into_owned()
}

fn prepare_file(
    display_path: &Path,
    regex: &Regex,
    replace_with: &str,
    max_replacements: usize,
    fixed_strings: bool,
) -> Result<PreparedFile, AppError> {
    let target_path = resolve_target_path(display_path)?;
    let file = File::open(&target_path).map_err(map_path_error(display_path))?;
    let permissions = file.metadata()?.permissions();
    let mmap = unsafe { MmapOptions::new().map(&file)? };
    let contents = replace_all(regex, &mmap, replace_with, max_replacements, fixed_strings);

    Ok(PreparedFile {
        display_path: display_path.to_path_buf(),
